(6495016, 964376, 14867, '<td valign="top">Blue lagoon...Nice, but not really pastel</td>', 'Blue lagoon...Nice, but not really pastel', '2011-08-06 04:21:23.000000', NULL, 1),
(6495054, 965273, 61788, '<td valign="top">Great idea - color and softness of yarn are really what goes with Pastel. Sharpness of bowl, despite color, I feel is not in line with Pastel concept (the way I interpret it; sorry, it is all about interpretation and it is subjective). I would have gone with even softer light (means larger light source), perhaps with a bowl that is not glazed, with cover of the table without green spots. Maybe some soft colored napkin would help with its softness. Don''t know what to say about fork - basically sharp contrasty elements kind of go against my interpretation of Pastel. I still love creative approach and feel it has much more potential.</td>', 'Great idea - color and softness of yarn are really what goes with Pastel. Sharpness of bowl, despite color, I feel is not in line with Pastel concept (the way I interpret it; sorry, it is all about interpretation and it is subjective). I would have gone with even softer light (means larger light source), perhaps with a bowl that is not glazed, with cover of the table without green spots. Maybe some soft colored napkin would help with its softness. Don''t know what to say about fork - basically sharp contrasty elements kind of go against my interpretation of Pastel. I still love creative approach and feel it has much more potential.', '2011-08-06 05:27:34.000000', NULL, 1),
(6495129, 965073, 123833, '<td valign="top">Incredible! A sure winner! I just showed it to my husband and he said WOW! (he does not say that often :)<br/>PS Have they spent some time in the fridge? Even if they did the arrangement is awesome! I think the one on the right is the sneaky leader ;)</td>', 'Incredible! A sure winner! I just showed it to my husband and he said WOW! (he does not say that often :)PS Have they spent some time in the fridge? Even if they did the arrangement is awesome! I think the one on the right is the sneaky leader ;)', '2011-08-06 07:23:04.000000', NULL, 1),
(6495130, 965102, 123833, '<td valign="top">Beautiful and delicate</td>', 'Beautiful and delicate', '2011-08-06 07:23:10.000000', NULL, 1),
(6495133, 965286, 123833, '<td valign="top">It does not look lived in (where is the mess?? :) but the colors are nice</td>', 'It does not look lived in (where is the mess?? :) but the colors are nice', '2011-08-06 07:24:08.000000', NULL, 1),
