(6499578, 965176, 70921, '<td valign="top">PERFECT composition, wonderful background but the bird is fuzzy.  Needs some point of focus somewhere.</td>', 'PERFECT composition, wonderful background but the bird is fuzzy.  Needs some point of focus somewhere.', '2011-08-09 17:56:52.000000', NULL, 1),
(6499580, 965091, 70921, '<td valign="top">Very nice composition and color</td>', 'Very nice composition and color', '2011-08-09 17:57:29.000000', NULL, 1),
(6499581, 965215, 70921, '<td valign="top">good composition and depth of field... maybe a little "too" washed out but a pretty pastel.</td>', 'good composition and depth of field... maybe a little "too" washed out but a pretty pastel.', '2011-08-09 17:58:06.000000', NULL, 1),
(6499583, 964154, 70921, '<td valign="top">Sharp... good depth of field, great composition not dead centered, perfect background... can''t find anything to complain about except I''d like to see it flipped to move the bug to the right third.  If it was that way I''d give it a 10.</td>', 'Sharp... good depth of field, great composition not dead centered, perfect background... can''t find anything to complain about except I''d like to see it flipped to move the bug to the right third.  If it was that way I''d give it a 10.', '2011-08-09 17:59:42.000000', NULL, 1),
(6499584, 964691, 70921, '<td valign="top">nice composition and boat placement... wonderful delicate pastel lighting... I want it on my wall!  Only thing I don''t like it the pink border only at top and bottom... lose it and get a 10!</td>', 'nice composition and boat placement... wonderful delicate pastel lighting... I want it on my wall!  Only thing I don''t like it the pink border only at top and bottom... lose it and get a 10!', '2011-08-09 18:00:54.000000', NULL, 1),
(6499590, 965151, 70921, '<td valign="top">I can''t think of a better way to compose this... everything is perfect from background to subject placement to leading lines, sharpness, color.... this should win something... can''t I give it an 11?</td>', 'I can''t think of a better way to compose this... everything is perfect from background to subject placement to leading lines, sharpness, color.... this should win something... can''t I give it an 11?', '2011-08-09 18:02:03.000000', NULL, 1),
(6499591, 964829, 70921, '<td valign="top">muddy lighting, distracting background and dead eyes</td>', 'muddy lighting, distracting background and dead eyes', '2011-08-09 18:02:36.000000', NULL, 1),
(6499593, 965259, 70921, '<td valign="top">Simply beautiful and well done</td>', 'Simply beautiful and well done', '2011-08-09 18:02:50.000000', NULL, 1),
(6499594, 965148, 70921, '<td valign="top">Change the name to "3 Windows" there isn''t any street!  LOVELY, well done, too bad you couldn''t take down that ugly distracting light fixture... without it I''d give it a 10.</td>', 'Change the name to "3 Windows" there isn''t any street!  LOVELY, well done, too bad you couldn''t take down that ugly distracting light fixture... without it I''d give it a 10.', '2011-08-09 18:04:12.000000', NULL, 1),
(6499596, 965285, 70921, '<td valign="top">Bug too small... get closer, looks like a picture of a log with a small unidentified bug I''d like to see more of.</td>', 'Bug too small... get closer, looks like a picture of a log with a small unidentified bug I''d like to see more of.', '2011-08-09 18:04:54.000000', NULL, 1),
(6499598, 964492, 70921, '<td valign="top">WOW at the detail in the shadows and what a beautiful pastel sky.  Nice composition with the barn in right third of photo.  The detail is wonderful. I''d call it "Big Sky"</td>', 'WOW at the detail in the shadows and what a beautiful pastel sky.  Nice composition with the barn in right third of photo.  The detail is wonderful. I''d call it "Big Sky"', '2011-08-09 18:05:54.000000', NULL, 1),
(6499601, 964678, 70921, '<td valign="top">Lovely color but I can''t identify any point of sharp focus.  Lady and child look blurry.  Also the composition is cut in half with the horizon line... needs some sky cropped out.</td>', 'Lovely color but I can''t identify any point of sharp focus.  Lady and child look blurry.  Also the composition is cut in half with the horizon line... needs some sky cropped out.', '2011-08-09 18:07:03.000000', NULL, 1),
(6499604, 965156, 70921, '<td valign="top">too much contrast across the photo, too much difference between petals that are highlights and those at far right that are shadows.</td>', 'too much contrast across the photo, too much difference between petals that are highlights and those at far right that are shadows.', '2011-08-09 18:08:06.000000', NULL, 1),
(6499605, 965149, 70921, '<td valign="top">Lovely pastel with good composition</td>', 'Lovely pastel with good composition', '2011-08-09 18:08:27.000000', NULL, 1),
(6499608, 964913, 70921, '<td valign="top">Good fill light on butterfly, like the leading diagonal line into the photo.  I''d crop top and right to position the butterfly off center and lose some of the "too much" sky that distracts from the subject.</td>', 'Good fill light on butterfly, like the leading diagonal line into the photo.  I''d crop top and right to position the butterfly off center and lose some of the "too much" sky that distracts from the subject.', '2011-08-09 18:09:41.000000', NULL, 1),
(6499609, 964720, 70921, '<td valign="top">lines tilt to the right... good focus and lighting</td>', 'lines tilt to the right... good focus and lighting', '2011-08-09 18:10:20.000000', NULL, 1),
(6499611, 965048, 70921, '<td valign="top">What an eye on this bird!  Good background, fantastic color and composition.  Wonderful color and lighting.</td>', 'What an eye on this bird!  Good background, fantastic color and composition.  Wonderful color and lighting.', '2011-08-09 18:11:03.000000', NULL, 1),
(6499612, 965169, 70921, '<td valign="top">Nice pose but skin looks muddy and underexposed.  The round shadow made from the microphone is very ugly on her face. The green shadows on her mouth and chin come off looking like bruises.</td>', 'Nice pose but skin looks muddy and underexposed.  The round shadow made from the microphone is very ugly on her face. The green shadows on her mouth and chin come off looking like bruises.', '2011-08-09 18:12:11.000000', NULL, 1),
