(6500817, 965284, 29011, '<td valign="top">Cool shot, Penny! Having one of my favorite buildings in the city reflected in another pretty cool building.</td>', 'Cool shot, Penny! Having one of my favorite buildings in the city reflected in another pretty cool building.', '2011-08-10 14:04:02.000000', NULL, 0),
(6500820, 964569, 29011, '<td valign="top">Most excellent shot. My top5 fave from the challenge. I didn''t vote but this quiet image speaks volumes to me. The shot looks good on my screen. No blown highlights are anything of the sort. If anything, perhaps would''ve liked the landline in the back to be slightly lighter in color.</td>', 'Most excellent shot. My top5 fave from the challenge. I didn''t vote but this quiet image speaks volumes to me. The shot looks good on my screen. No blown highlights are anything of the sort. If anything, perhaps would''ve liked the landline in the back to be slightly lighter in color.', '2011-08-10 14:06:34.000000', NULL, 0),
(6500822, 965174, 118154, '<td valign="top">Sorry about the camera,I feel bad about moaning now.</td>', 'Sorry about the camera,I feel bad about moaning now.', '2011-08-10 14:07:51.000000', NULL, 0),
